import Foundation

// Packed Unicode 17.0 property tables. Each is base64 of a byte stream of
// (varint Δ, value) pairs: walking it yields the ascending code points where
// the packed value changes. A code point's value is that of the nearest change
// point at or below it, and 0 before the first.
struct UnicodeTable: Sendable {
	private let starts: [UInt32]
	private let values: [UInt8]

	init(base64: String) {
		let bytes = [UInt8](Data(base64Encoded: base64)!)
		var starts: [UInt32] = []
		var values: [UInt8] = []
		var position = 0
		var codePoint: UInt32 = 0
		while position < bytes.count {
			var shift: UInt32 = 0
			var delta: UInt32 = 0
			var byte: UInt8
			repeat {
				byte = bytes[position]
				position += 1
				delta |= UInt32(byte & 0x7f) << shift
				shift += 7
			} while byte & 0x80 != 0
			codePoint += delta
			starts.append(codePoint)
			values.append(bytes[position])
			position += 1
		}
		self.starts = starts
		self.values = values
	}

	/// The packed property value for a code point.
	subscript(codePoint: UInt32) -> Int {
		var low = 0
		var high = starts.count - 1
		var value: UInt8 = 0
		while low <= high {
			let mid = (low + high) >> 1
			if starts[mid] <= codePoint {
				value = values[mid]
				low = mid + 1
			} else {
				high = mid - 1
			}
		}
		return Int(value)
	}

	// Grapheme_Cluster_Break | Indic_Conjunct_Break << 4 |
	// Extended_Pictographic << 6. See Grapheme.swift.
	static let grapheme = UnicodeTable(
		base64:
			""
	)

	// WIDE | NON_CONTRIBUTING | EMOJI_VS_BASE. See Width.swift.
	static let width = UnicodeTable(
		base64:
			""
	)
}
